"""Every M1 contract folder exists, and every sample validates against its schema and type."""

import importlib.util
import math
import sys
import types
from pathlib import Path
from typing import Any

import numpy as np
import pytest

from rllab.core import EVAL_SEEDS, FINAL_SEEDS


def _load_contracts() -> types.ModuleType:
    if "contracts" not in sys.modules:
        spec = importlib.util.spec_from_file_location(
            "contracts", Path(__file__).with_name("contracts.py")
        )
        assert spec is not None
        assert spec.loader is not None
        module = importlib.util.module_from_spec(spec)
        sys.modules["contracts"] = module
        spec.loader.exec_module(module)
    return sys.modules["contracts"]


contracts = _load_contracts()

M1_FOLDERS = {
    "core.ActionSpace", "core.TeamSpec", "core.WorldSpec", "core.Step", "core.EpisodeResult",
    "core.DrawState", "core.Frame", "core.Episode", "core.World", "core.Policy",
    "core.play_episode", "core.EVAL_SEEDS", "core.FINAL_SEEDS", "core.Output",
    "worlds.make", "worlds.CheckWorld",
    "baselines.RandomPolicy", "baselines.RulePolicy", "baselines.rule_for",
    "baselines.BaselineMeans", "baselines.baseline_means",
    "methods.MethodConfig", "methods.Transition", "methods.Learner", "methods.make_learner",
    "methods.load_policy",
    "train.RunConfig", "train.load_run_configs", "train.run_check", "train.run_train",
    "train.run_batch", "train.CheckResult",
    "runlog.RunRecord", "runlog.EvalPoint", "runlog.Checkpoint", "runlog.Run", "runlog.RunWriter",
    "runlog.find_runs", "runlog.open_run", "runlog.Progress", "runlog.progress",
    "charts.learning_curve",
    "evaluate.Comparison", "evaluate.Summary", "evaluate.final_evaluation",
}  # fmt: skip
SAMPLES = [(symbol, case) for symbol in contracts.folders() for case in contracts.cases(symbol)]
DATA = [(symbol, case) for symbol, case in SAMPLES if symbol in contracts.TYPES]


def _close(left: Any, right: Any) -> bool:
    """JSON values equal, floats to float32 precision, NaN equal to NaN."""
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(_close(left[k], right[k]) for k in left)
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(map(_close, left, right))
    if isinstance(left, float) and isinstance(right, (int, float)):
        both_nan = math.isnan(left) and math.isnan(right)
        return both_nan or math.isclose(left, right, rel_tol=1e-6, abs_tol=1e-9)
    return type(left) is type(right) and left == right


def test_every_m1_boundary_symbol_has_its_folder() -> None:
    assert set(contracts.folders()) == M1_FOLDERS


@pytest.mark.parametrize("symbol", sorted(M1_FOLDERS))
def test_each_folder_holds_samples_with_a_schema_or_a_fake(symbol: str) -> None:
    folder = contracts.ROOT / symbol
    has_samples = (folder / "schema.json").is_file() and bool(contracts.cases(symbol))
    assert has_samples or (folder / "fake.py").is_file()


@pytest.mark.parametrize(("symbol", "case"), SAMPLES)
def test_sample_validates_against_its_schema(symbol: str, case: str) -> None:
    assert contracts.validate(contracts.raw(symbol, case), symbol) == []


@pytest.mark.parametrize(("symbol", "case"), DATA)
def test_data_sample_decodes_to_its_type_and_back(symbol: str, case: str) -> None:
    assert _close(contracts.encode(contracts.sample(symbol, case)), contracts.raw(symbol, case))


def test_the_schema_check_catches_broken_samples() -> None:
    spec = contracts.raw("core.WorldSpec", "snake_default")
    assert contracts.validate({**spec, "obs_len": "12"}, "core.WorldSpec") == [
        "$.obs_len: expected integer, got str"
    ]
    assert contracts.validate({**spec, "extra": 1}, "core.WorldSpec") == ["$: unexpected 'extra'"]
    missing = {k: v for k, v in spec.items() if k != "sight"}
    assert contracts.validate(missing, "core.WorldSpec") == ["$: missing 'sight'"]
    both = {"n": 3, "dims": 2, "low": -1.0, "high": 1.0}
    assert contracts.validate(both, "core.ActionSpace") == ["$: matches 0 of oneOf, not exactly 1"]
    bad_team = {**spec, "teams": [{**spec["teams"][0], "direction": "up"}]}
    assert contracts.validate(bad_team, "core.WorldSpec") == [
        "$.teams[0].direction: 'up' not in ['higher', 'lower']"
    ]


def test_seed_sets_match_their_samples_and_are_disjoint() -> None:
    assert contracts.sample("core.EVAL_SEEDS", "seeds") == EVAL_SEEDS
    assert contracts.sample("core.FINAL_SEEDS", "seeds") == FINAL_SEEDS
    assert min(EVAL_SEEDS) >= 1_000_000
    assert not set(EVAL_SEEDS) & set(FINAL_SEEDS)


def test_action_space_samples_decode_to_discrete_and_box() -> None:
    snake = contracts.sample("core.ActionSpace", "snake_discrete")
    fish = contracts.sample("core.ActionSpace", "fish_box")
    assert (type(snake).__name__, snake.n) == ("Discrete", 3)
    assert (type(fish).__name__, fish.dims, fish.low, fish.high) == ("Box", 2, -1.0, 1.0)


@pytest.mark.parametrize("case", ["snake_default", "fish_local", "prey_default"])
def test_world_spec_teams_are_disjoint_and_cover_every_agent(case: str) -> None:
    spec = contracts.sample("core.WorldSpec", case)
    members = [agent for team in spec.teams for agent in team.agents]
    assert sorted(members) == list(range(len(spec.agents)))
    assert {m.team for m in spec.measures} <= {t.name for t in spec.teams}


def test_step_samples_have_the_contract_dtypes_and_zeroed_inactive_rows() -> None:
    for case in contracts.cases("core.Step"):
        step = contracts.sample("core.Step", case)
        assert (step.obs.dtype, step.rewards.dtype, step.active.dtype) == (
            np.float32,
            np.float32,
            np.bool_,
        )
        assert len(step.obs) == len(step.rewards) == len(step.active)
        assert not step.obs[~step.active].any()
        assert not step.rewards[~step.active].any()
    caught = contracts.sample("core.Step", "prey_one_caught")
    assert caught.active.tolist().count(False) == 1


@pytest.mark.parametrize(
    ("symbol", "case"),
    [("core.Episode", "check_traced_3step"), ("core.play_episode", "snake_rule_seed7_traced")],
)
def test_traced_episodes_have_one_frame_per_step_plus_the_reset(symbol: str, case: str) -> None:
    episode = contracts.sample(symbol, case)
    assert [f.step for f in episode.frames] == list(range(episode.result.length + 1))
    assert not episode.frames[0].rewards.any()
    assert episode.frames[-1].scores == episode.result.scores


def test_frame_samples_are_the_first_frames_of_the_seed7_episode() -> None:
    episode = contracts.sample("core.play_episode", "snake_rule_seed7_traced")
    for index, case in enumerate(["snake_seed7_frame0", "snake_seed7_frame1"]):
        assert contracts.same(contracts.sample("core.Frame", case), episode.frames[index])


@pytest.mark.parametrize("case", ["dqn_pass", "ppo_fail"])
def test_check_result_passes_exactly_at_95_percent_agreement(case: str) -> None:
    result = contracts.sample("train.CheckResult", case)
    assert result.passed == (result.agreement >= 0.95)


@pytest.mark.parametrize("case", ["snake_pass", "snake_failing_run", "snake_3_runs"])
def test_summary_means_ranges_and_run_counts_agree(case: str) -> None:
    summary = contracts.sample("evaluate.Summary", case)
    means = [summary.run_means[name] for name in summary.runs]
    assert summary.learned_mean == pytest.approx(sum(means) / len(means))
    assert summary.learned_range == (min(means), max(means))
    assert summary.verdict.runs_needed == max(0, 5 - len(summary.runs))
    assert (summary.comparisons == ()) == (len(summary.runs) < 5)
    rule = [c for c in summary.comparisons if c.baseline == "rule"]
    failing = tuple(name for name in summary.runs if summary.run_means[name] <= summary.rule_mean)
    assert summary.verdict.failing_runs == failing
    assert summary.verdict.beats_baselines == (
        bool(rule) and not failing and all(c.rejected for c in summary.comparisons)
    )


def test_comparison_differences_are_signed_toward_better() -> None:
    for case in contracts.cases("evaluate.Comparison"):
        c = contracts.sample("evaluate.Comparison", case)
        assert c.difference == pytest.approx(c.learned_mean - c.baseline_mean)
        assert c.p_holm >= c.p_raw
        assert c.rejected == (c.p_holm <= 0.05)


def test_run_record_samples_cover_finished_failed_and_incomplete() -> None:
    records = {case: contracts.sample("runlog.RunRecord", case) for case in contracts.cases("runlog.RunRecord")}
    assert {r.status for r in records.values()} == {"finished", "failed", "incomplete"}
    failed = records["snake_failed_nan"]
    assert failed.failure.step == 41_200
    assert math.isnan(failed.failure.value)
    assert records["snake_incomplete"].ended is None
    assert all((r.failure is None) == (r.status != "failed") for r in records.values())

